import heapq


class CycleError(Exception):
    pass


def order(deps):
    # Every node mentioned anywhere: keys and anything listed as a dependency.
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)

    # Unique dependencies per node (a repeated dep must not count twice).
    dep_map = {node: set(deps.get(node, ())) for node in nodes}

    # remaining[n] = number of dependencies of n not yet emitted.
    remaining = {node: len(ds) for node, ds in dep_map.items()}

    # dependents[d] = nodes that list d as a dependency.
    dependents = {node: [] for node in nodes}
    for node, ds in dep_map.items():
        for d in ds:
            dependents[d].append(node)

    # Kahn's algorithm: always pick the smallest currently-ready node,
    # re-evaluating readiness after every pick.
    ready = [node for node in nodes if remaining[node] == 0]
    heapq.heapify(ready)
    out = []
    while ready:
        node = heapq.heappop(ready)
        out.append(node)
        for m in dependents[node]:
            remaining[m] -= 1
            if remaining[m] == 0:
                heapq.heappush(ready, m)

    if len(out) != len(nodes):
        raise CycleError()
    return out

